effect.shader:
float hash11(float n){ return fract(sin(n * 127.1 + 311.7) * 43758.5453); }
float smoothRect(float x, float halfW){
return 1.0 - smoothstep(halfW - 1e-4, halfW + 1e-4, abs(x));
}
float smoothLine(float y, float halfT){
return 1.0 - smoothstep(halfT - 1e-4, halfT + 1e-4, abs(y));
}
float smoothCircle(vec2 p, float r){
float d = length(p);
return 1.0 - smoothstep(r - 1e-4, r + 1e-4, d);
}
float bandAmp(float i, float N){
float base = pow(audio_level, reactivity);
float rnd = (hash11(i + seed) * 2.0 - 1.0) * jitter;
float wob = 0.5 + 0.5 * sin(acTime * (2.5 * speed) + i * 0.9);
float env = 0.85 - 0.35 * abs((i/(N-1.0)) * 2.0 - 1.0);
float amp = clamp(base * env * (0.6 + 0.8 * wob + rnd), 0.0, 1.0);
return amp;
}
void main(){
vec2 uv = acScreenNorm;
float margin = clamp(left_margin, 0.0, 0.49);
float N = float(bar_count);
float usableW = 1.0 - 2.0 * margin;
float xIn = (uv.x - margin) / max(usableW, 1e-4);
if(xIn < 0.0 || xIn > 1.0){ gl_FragColor = vec4(0.0); return; }
float i = floor(xIn * N);
float cx = margin + (i + 0.5) / N * usableW;
float dx = uv.x - cx;
float amp = bandAmp(i, N);
float h = bar_max_height * amp;
float halfW = bar_width * 0.5;
float baseline = baseline_y;
float cov = 0.0;
cov = max(cov, smoothLine(uv.y - baseline, line_thickness * 0.5));
float cxCov = smoothRect(dx, halfW);
float yTop = baseline + h;
float yBot = baseline - h;
float yDist = max(0.0, max(uv.y - yTop, yBot - uv.y));
float yCov = 1.0 - smoothstep(0.0, 1e-4, yDist);
cov = max(cov, cxCov * yCov);
float nextCx = margin + (i + 1.0) / N * usableW;
float midX = mix(cx, nextCx, 0.5);
vec2 dp = vec2(uv.x - midX, uv.y - baseline);
cov = max(cov, smoothCircle(dp, dot_size));
vec3 col = color.rgb;
float a = cov * alpha;
gl_FragColor = vec4(col * a, a);
}
